widget.solution:
def fib_memo(n):
    cache = {}
    computed = 0

    def f(k):
        nonlocal computed
        if k in cache:
            return cache[k]
        computed += 1
        value = k if k < 2 else f(k - 1) + f(k - 2)
        cache[k] = value
        return value

    return f(n), computed


def grid_paths(r, c):
    cache = {}

    def paths(i, j):
        if i == 1 or j == 1:
            return 1
        if (i, j) not in cache:
            cache[(i, j)] = paths(i - 1, j) + paths(i, j - 1)
        return cache[(i, j)]

    return paths(r, c)

